from flask import Flask, jsonify, request, abort
from datetime import datetime
from copy import deepcopy
import uuid

app = Flask(__name__)

state = {
    "users": {
        "admin": {"role": "administrator"},
        "pm": {"role": "project_manager"},
        "analyst": {"role": "analyst"},
        "guest": {"role": "guest"},
    },
    "projects": {},
    "glossary": {
        "policy": {"definition": "An approved rule or source policy.", "examples": ["Privacy Policy", "Security Policy"]},
        "goal": {"definition": "A desired outcome.", "examples": ["Reduce risk"]},
        "requirement": {"definition": "A system requirement.", "examples": ["Must log changes"]},
    },
    "notifications": [],
}


def now():
    return datetime.utcnow().isoformat() + "Z"


def get_user():
    username = request.headers.get("X-User", "guest")
    return username, state["users"].get(username, state["users"]["guest"])


def require_roles(*roles):
    def decorator(fn):
        def wrapper(*args, **kwargs):
            _, user = get_user()
            if user["role"] not in roles:
                abort(403)
            return fn(*args, **kwargs)
        wrapper.__name__ = fn.__name__
        return wrapper
    return decorator


def get_project(pid):
    project = state["projects"].get(pid)
    if not project:
        abort(404)
    return project


def add_notification(text):
    state["notifications"].append({"id": str(uuid.uuid4()), "message": text, "timestamp": now()})


@app.get("/health")
def health():
    return {"status": "ok"}


@app.get("/glossary/<term>")
def glossary(term):
    entry = state["glossary"].get(term.lower())
    if not entry:
        return {"term": term, "known": False, "suggestions": list(state["glossary"].keys())}
    return {"term": term, "known": True, **entry}


@app.post("/projects")
@require_roles("administrator", "project_manager")
def create_project():
    data = request.get_json(force=True)
    pid = str(uuid.uuid4())
    state["projects"][pid] = {
        "id": pid,
        "name": data.get("name", "Untitled Project"),
        "artifacts": {},
        "links": {},
        "imports": [],
        "conflicts": [],
    }
    return jsonify(state["projects"][pid]), 201


@app.get("/projects")
def list_projects():
    return jsonify(list(state["projects"].values()))


@app.post("/projects/<pid>/artifacts")
@require_roles("administrator", "project_manager", "analyst")
def create_artifact(pid):
    project = get_project(pid)
    data = request.get_json(force=True)
    term = data.get("title", "").strip()
    warnings = []
    if term and term.lower() in state["glossary"]:
        warnings.append("term matches existing glossary entry")
    for existing in project["artifacts"].values():
        if existing["title"].lower() == term.lower() and term:
            warnings.append("likely duplicate artifact title")
    aid = str(uuid.uuid4())
    artifact = {
        "id": aid,
        "title": term or "Untitled",
        "type": data.get("type", "requirement"),
        "content": data.get("content", ""),
        "status": data.get("status", "draft"),
        "version": 1,
        "versions": [],
        "trace_links": data.get("trace_links", []),
        "comments": [],
        "created_at": now(),
        "updated_at": now(),
        "warnings": warnings,
    }
    project["artifacts"][aid] = artifact
    return jsonify(artifact), 201


@app.get("/projects/<pid>/artifacts")
def list_artifacts(pid):
    project = get_project(pid)
    return jsonify(list(project["artifacts"].values()))


@app.put("/projects/<pid>/artifacts/<aid>")
@require_roles("administrator", "project_manager", "analyst")
def update_artifact(pid, aid):
    project = get_project(pid)
    artifact = project["artifacts"].get(aid)
    if not artifact:
        abort(404)
    _, user = get_user()
    if artifact["status"] == "approved" and user["role"] != "administrator":
        return jsonify({"error": "approved artifacts require new version or admin reopen"}), 409
    data = request.get_json(force=True)
    artifact["versions"].append(deepcopy({k: artifact[k] for k in ["title", "content", "status", "trace_links"]}))
    artifact["version"] += 1
    artifact["title"] = data.get("title", artifact["title"])
    artifact["content"] = data.get("content", artifact["content"])
    artifact["status"] = data.get("status", artifact["status"])
    artifact["trace_links"] = data.get("trace_links", artifact["trace_links"])
    artifact["updated_at"] = now()
    return jsonify(artifact)


@app.post("/projects/<pid>/links")
@require_roles("administrator", "project_manager", "analyst")
def create_link(pid):
    project = get_project(pid)
    data = request.get_json(force=True)
    link_id = str(uuid.uuid4())
    project["links"][link_id] = {
        "id": link_id,
        "from": data.get("from"),
        "to": data.get("to"),
        "created_at": now(),
        "broken": False,
    }
    return jsonify(project["links"][link_id]), 201


@app.get("/projects/<pid>/conflicts")
def conflicts(pid):
    project = get_project(pid)
    return jsonify(project["conflicts"])


@app.post("/projects/<pid>/imports")
@require_roles("administrator", "project_manager", "analyst")
def import_data(pid):
    project = get_project(pid)
    data = request.get_json(force=True)
    staging = []
    unresolved = []
    for item in data.get("items", []):
        mapped = deepcopy(item)
        mapped.setdefault("source_value", item.get("title", ""))
        if not item.get("title"):
            unresolved.append(mapped)
            mapped["review_required"] = True
        staging.append(mapped)
    project["imports"].append({"id": str(uuid.uuid4()), "staging": staging, "unresolved": unresolved, "status": "staged"})
    return jsonify({"staged": len(staging), "unresolved": len(unresolved)}), 201


@app.get("/notifications")
def notifications():
    return jsonify(state["notifications"])


@app.post("/projects/<pid>/simulate-conflict")
@require_roles("administrator", "project_manager", "analyst")
def simulate_conflict(pid):
    project = get_project(pid)
    conflict = {"id": str(uuid.uuid4()), "message": "Overlapping edits detected", "status": "needs review", "created_at": now()}
    project["conflicts"].append(conflict)
    add_notification(f"Conflict in project {project['name']}")
    return jsonify(conflict), 201


if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8000, debug=False)
EOF

